<script setup>
import {computed} from 'vue';
const props=defineProps({form:Object,catalog:Object});
const total=computed(()=>(props.form.blueprint||[]).reduce((n,r)=>n+(Number(r.count)||0),0));
function add(){props.form.blueprint.push({subject:props.form.subjects[0],topic:'',difficulty:'All',count:1})}
function topics(s){return props.catalog.topics.filter(t=>t.subject===s&&(!props.form.topics.length||props.form.topics.includes(s+'\u001f'+t.topic)))}
</script>
<template><div class="quota-editor"><p>Set a count for each subject, topic, and difficulty combination. Overlapping rows draw different questions.</p><article v-for="(r,i) in form.blueprint" :key="i" class="inset quota-row"><label>Subject<select v-model="r.subject" @change="r.topic=''"><option v-for="s in form.subjects" :key="s">{{s}}</option></select></label><label>Topic<select v-model="r.topic"><option value="">All selected topics</option><option v-for="t in topics(r.subject)" :key="t.topic">{{t.topic}}</option></select></label><label>Difficulty<select v-model="r.difficulty"><option v-for="d in ['All','Easy','Average','Difficult']" :key="d">{{d}}</option></select></label><label>Questions<input type="number" v-model.number="r.count" min="1" max="10000"></label><button type="button" @click="form.blueprint.splice(i,1)" :aria-label="'Remove quota row '+(i+1)">Remove</button></article><div class="row"><button type="button" :disabled="form.blueprint.length>=120" @click="add">Add quota row</button><strong>{{total}} / {{form.count}} questions allocated</strong></div><button v-if="total>0&&total!==form.count" type="button" @click="form.count=total">Use {{total}} as the exam total</button></div></template>
<style scoped>.quota-row{display:grid;grid-template-columns:minmax(120px,1fr) minmax(180px,2fr) minmax(100px,1fr) 90px auto;gap:12px;align-items:end}.quota-row label{min-width:0}.quota-row select{max-width:100%}@media(max-width:900px){.quota-row{grid-template-columns:1fr 1fr}}@media(max-width:550px){.quota-row{grid-template-columns:1fr}}</style>
